constraint forall(i in 1..4) (
    (pen[i] = rabbit) -> (pen[i+1] = wolf)
);

% Wolf preys on the rabbit
constraint pen[5] = wolf; % Since rabbit must be in lower-numbered pen

% Ensure all animals are placed in the pens
constraint alldifferent(pen);

include "globals.mzn";

enum Animal = {Tortoise, Parrot, Goat, Rabbit, Wolf};
array[1..5] of var Animal: pens;

% Constraints
constraint pens[1] == Tortoise;
constraint pens[2] == Parrot;
constraint pens[3] == Goat;

% Rabbit is in a lower-numbered pen than the Wolf
constraint forall(i in 1..5) (
    (pens[i] == Rabbit) -> (exists(j in (i+1)..5)(pens[j] == Wolf))
);

% Wolf preys on the Rabbit
constraint forall(i in 1..5) (
    pens[i] == Wolf -> exists(j in 1..5)(pens[j] == Rabbit) 
);

% All different animals in different pens
constraint alldifferent(pens);

include "globals.mzn";

enum Animal = {Tortoise, Parrot, Goat, Rabbit, Wolf};
array[1..5] of var Animal: animalInPen;

constraint animalInPen[1] = Tortoise;
constraint animalInPen[2] = Parrot;
constraint animalInPen[3] = Goat;

constraint animalInPen[4] = Rabbit;
constraint animalInPen[5] = Wolf;

constraint forall(i in 1..5)(animalInPen[i] != animalInPen[i+1]) where i < 5;

constraint animalInPen[4] = Rabbit;  % Rabbit must be in a lower-numbered pen than the Wolf
constraint animalInPen[5] = Wolf;    % Wolf preys on the Rabbit
